# validate coverage and generate deploy content
slugs={x['slug'] for x in A};assert len(slugs)==len(A)
base=Path('/Volumes/MacOSDisk/Oath App')
coverage=[]
for a in A:
 missing=[p for p in a['source'] if not (base/p).exists()]
 coverage.append({'slug':a['slug'],'title':a['title'],'sources':a.pop('source'),'source_paths_missing':missing})
 a['related']=[x['slug'] for x in A if x['category_id']==a['category_id'] and x['slug']!=a['slug']][:3]
 a['sort_order']=len([x for x in A[:A.index(a)] if x['category_id']==a['category_id']]) if False else A.index(a)
data={'categories':[dict(id=id,title=t,description=d,icon=i,sort_order=n) for n,(id,t,d,i) in enumerate(C)],'articles':A,'version':'2026-10-12.1'}
(ROOT/'src/help/content.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
(ROOT/'Reports/help-center-2026-10-12/coverage.json').write_text(json.dumps(coverage,indent=2)+'\n')
print('Authored',len(A),'articles in',len(C),'collections')
print('Source paths to resolve:',[(a['slug'],a['source_paths_missing']) for a in coverage if a['source_paths_missing']])
